DM.def('composer', (r, c) => {
  const icons = { plus:'plus', folder:'folder', laptop:'laptop', cloud:'cloud', mic:'mic', up:'up', x:'x', check:'check', clip:'clip', image:'image', figma:'figma', at:'at', slash:'slash', branch:'branch' };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => icons[k] ? I(icons[k]) : m);
  const box = $('.cpx-box', r), ta = $('.cpx-ta', r), send = $('.cpx-bar .cpx-send', r), cv = $('.cpx-wave', r), thread = $('.cpx-thread', r), att = $('.cpx-att', r);
  const grow = () => { ta.style.height = 'auto'; ta.style.height = Math.min(ta.scrollHeight, 160) + 'px'; };
  const sync = () => { send.disabled = !ta.value.trim() && !att.children.length; grow(); };
  c.on(ta, 'input', sync);
  c.on(ta, 'keydown', e => { if (e.key === 'Enter' && !e.shiftKey && box.dataset.mode === 'idle'){ e.preventDefault(); submit(); } if (e.key === 'Escape' && box.dataset.mode === 'voice') stopVoice(false); });
  /* plus menu */
  const ATT = { file:['file-text','brief.pdf'], shot:['image','Screenshot 10.42'], figma:['figma','Pricing / Desktop'] };
  $$('[data-add]', r).forEach(b => b.onclick = () => { const a = ATT[b.dataset.add]; const ch = html(`<span class="fchip">${I(a[0],'xs')}${a[1]}<button class="x" aria-label="Remove ${a[1]}">${I('x','xs')}</button></span>`); att.appendChild(ch); enter(ch); $('.x', ch).onclick = () => { ch.classList.add('leave'); setTimeout(() => { ch.remove(); sync(); }, 300); }; sync(); });
  $$('[data-ins]', r).forEach(b => b.onclick = () => { ta.value += (ta.value && !ta.value.endsWith(' ') ? ' ' : '') + b.dataset.ins; ta.focus(); sync(); });
  const radio = (sel, attr, fn) => $$(sel, r).forEach(b => b.onclick = () => { $$(sel, r).forEach(x => x.setAttribute('aria-checked', x === b)); fn(b.dataset[attr]); });
  radio('[data-proj]', 'proj', v => swap($('.cpx-proj', r), v));
  radio('[data-env]', 'env', v => { swap($('.cpx-env', r), v); const ch = $('[data-pop=".pp-env"]', r); ch.querySelector('svg').outerHTML = I({ Local:'laptop', Worktree:'branch', Cloud:'cloud' }[v]); });
  const effN = ['','Low','Medium','High'];
  radio('[data-eff]', 'eff', v => { const b = $('.cpx-eff', r); $$('.cpx-bar .cpx-bars i', r).forEach((x, i) => x.classList.toggle('on', i < +v)); b.dataset.tip = 'Effort: ' + effN[v]; });
  const cr = $('.cc-row', r); cr.onclick = () => { const on = cr.getAttribute('aria-checked') !== 'true'; cr.setAttribute('aria-checked', on); $('.cpx-cloud', r).classList.toggle('on', on); $('.cpx-cloud', r).dataset.tip = on ? 'Hands off to the cloud when you close your laptop' : 'Hand off to the cloud'; };
  /* dictation, played from a sample because the page can't use a microphone */
  const said = 'Can you tighten the spacing on the pricing cards and keep the buttons the same height? Then run the visual tests before you open the PR.';
  let samples = [], speaking = 0, last = 0, before = '', vc = null;
  function draw(t){
    if (box.dataset.mode !== 'voice') return false;
    if (t - last > 55){ last = t; samples.push(speaking > 0 ? Math.min(1, .25 + Math.random() * .75 * (.6 + .4 * Math.sin(t / 90))) : 0); if (samples.length > 400) samples.shift(); if (speaking > 0) speaking--; }
    const dpr = devicePixelRatio || 1, w = cv.clientWidth, h = cv.clientHeight; if (!w) return;
    if (cv.width !== w * dpr){ cv.width = w * dpr; cv.height = h * dpr; }
    const x = cv.getContext('2d'); x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, w, h);
    const cs = getComputedStyle(r), col = cs.getPropertyValue('--fg2').trim(), faint = cs.getPropertyValue('--faint').trim();
    const step = 3.5, n = Math.floor(w / step);
    for (let i = 0; i < n; i++){ const v = samples[samples.length - n + i], px = i * step + 1, mid = h / 2, fade = Math.min(1, i / 18);
      x.globalAlpha = fade;
      if (!v){ x.fillStyle = faint; x.fillRect(px, mid - .6, 1.2, 1.2); } else { const bh = Math.max(3, v * (h - 6)); x.fillStyle = col; x.beginPath(); x.roundRect ? x.roundRect(px, mid - bh / 2, 2, bh, 1) : x.rect(px, mid - bh / 2, 2, bh); x.fill(); } }
    x.globalAlpha = 1;
  }
  async function dictate(){
    if (vc) vc.stop(); vc = ctl(); const k = vc; c.offs.push(() => k.stop());
    before = ta.value; samples = []; speaking = 0; box.dataset.mode = 'voice'; ta.value = ''; ta.placeholder = 'Listening…'; grow();
    c.loop(draw);
    await k.run(async () => {
      await k.wait(900);
      for (const w of said.split(' ')){ speaking = 6; ta.value += (ta.value ? ' ' : '') + w; grow(); await k.wait(150 + Math.random() * 140 + (/[?.,]$/.test(w) ? 520 : 0)); }
    });
  }
  function stopVoice(keep){ if (vc) vc.stop(); box.dataset.mode = 'idle'; ta.placeholder = 'Ask anything, or type / for skills'; if (!keep) ta.value = before; sync(); ta.focus(); }
  $('.cpx-mic', r).onclick = dictate;
  $('.cpx-cancel', r).onclick = () => stopVoice(false);
  $('.cpx-ok', r).onclick = () => stopVoice(true);
  function submit(){
    const v = ta.value.trim(); if (!v && !att.children.length) return;
    const files = $$('.fchip', att).map(f => f.textContent.trim());
    ta.value = ''; att.innerHTML = ''; sync();
    const b = html(`<div class="bub">${files.length ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:${v ? 6 : 0}px">${files.map(f => `<span class="fchip">${I('clip','xs')}${f}</span>`).join('')}</div>` : ''}${v.replace(/</g,'&lt;')}</div>`); thread.appendChild(b); enter(b);
    const a = html(`<div class="cpx-ag"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Thinking</span></div>`); thread.appendChild(a); enter(a);
    while (thread.children.length > 4) thread.firstElementChild.remove();
    c.later(1700, () => { a.innerHTML = '<span>On it. I\'ll start with the pricing cards.</span>'; enter(a); });
  }
  send.onclick = submit;
  sync();
});

