DM.def('agent-lanes', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{users}', I('users')).replace('{pause}', I('pause','xs'));
  const L = [
    { n:'Researcher', ic:'search', col:'var(--pb)', bg:'var(--pb-bg)', acts:['Reading competitor sites','Comparing 5 pricing pages','Writing the brief'], log:['Read stripe.com/pricing','Read linear.app/pricing','Noted 3 patterns'] },
    { n:'Designer', ic:'palette', col:'var(--pl)', bg:'var(--pl-bg)', wait:'Waiting for the brief', acts:['Laying out pricing cards','Setting type and spacing','Exporting frames'], log:['Made 3 card variants','Applied spacing tokens','Exported 4 frames'] },
    { n:'Reviewer', ic:'eye', col:'var(--pm)', bg:'var(--pm-bg)', wait:'Waiting for the designer', acts:['Checking contrast','Checking copy','Signing off'], log:['Contrast passes AA','Fixed 2 lines of copy','Approved'] }
  ];
  const rows = $('.aln-rows', r);
  L.forEach(l => {
    l.el = html(`<div class="aln-lane"><button class="aln-row" aria-expanded="false"><span class="aln-av" style="background:${l.bg};color:${l.col}">${I(l.ic)}</span><span><span class="aln-n">${l.n}</span><span class="aln-a">${l.wait || 'Queued'}</span></span><span class="aln-tr" style="--c:${l.col}"><i></i><i></i><i></i></span><span class="aln-st"><span class="tag">Queued</span></span></button><div class="fold shut"><div><div class="aln-det"></div></div></div></div>`);
    rows.appendChild(l.el); const b = $('.aln-row', l.el), f = $('.fold', l.el);
    b.onclick = () => { const s = f.classList.toggle('shut'); b.setAttribute('aria-expanded', !s); };
  });
  const st = (l, h) => { const s = $('.aln-st', l.el); s.innerHTML = h; enter(s.firstElementChild); };
  const act = (l, t, live) => { const a = $('.aln-a', l.el); a.classList.toggle('live', !!live); swap(a, t); };
  let paused = false, secs = 0, finished = false;
  const pb = $('.aln-pause', r);
  pb.onclick = () => { paused = !paused; pb.innerHTML = I(paused ? 'play' : 'pause','xs') + (paused ? 'Resume' : 'Pause all'); swap($('.aln-t', r), paused ? 'All agents paused' : '3 agents working'); L.forEach(l => { if (l.running) st(l, paused ? '<span class="tag warn">Paused</span>' : '<span class="tag b"><span class="spin" style="width:9px;height:9px"></span>Working</span>'); }); };
  c.every(1000, () => { if (!paused && !finished){ secs++; $('.aln-m', r).textContent = Math.floor(secs / 60) + ':' + String(secs % 60).padStart(2, '0'); } });
  const hold = async ms => { let t = 0; while (t < ms){ await c.wait(100); if (!paused) t += 100; } };
  async function work(l){
    l.running = true; st(l, '<span class="tag b"><span class="spin" style="width:9px;height:9px"></span>Working</span>');
    const bars = $$('.aln-tr i', l.el), det = $('.aln-det', l.el);
    for (let i = 0; i < 3; i++){
      bars[i].classList.add('run'); act(l, l.acts[i], true);
      await hold(1500);
      bars[i].classList.remove('run'); bars[i].classList.add('on');
      const d = html(`<div><span>${l.log[i]}</span><span class="muted">${secs}s</span></div>`); det.appendChild(d); enter(d);
    }
    l.running = false; act(l, l.log[2]); st(l, `<span class="tag ok">${I('check','xs')}Done</span>`);
  }
  async function handoff(from, to, txt){
    const h = html(`<div class="fold shut aln-hf"><div><div class="aln-hand">${I('right','xs')}${from.n} handed ${txt} to ${to.n}</div></div></div>`);
    to.el.before(h); void h.offsetWidth; h.classList.remove('shut'); enter($('.aln-hand', h), 80);
    await c.wait(1700); h.classList.add('shut'); await c.wait(REDUCE ? 0 : 700); h.remove();
  }
  c.run(async () => {
    await c.wait(600);
    const r1 = work(L[0]); act(L[1], L[1].wait); st(L[1], '<span class="tag">Waiting</span>');
    await r1; await handoff(L[0], L[1], 'the brief');
    const r2 = work(L[1]); await r2; await handoff(L[1], L[2], '4 frames');
    await work(L[2]);
    finished = true; swap($('.aln-t', r), 'All 3 agents finished'); pb.remove();
  });
});

