  r.innerHTML = r.innerHTML.replace('{up}', I('up')).replace('{shuffle}', I('refresh','xs'));
  const sets = [
    [['grid','var(--pb)','var(--pb-bg)','Audit a page','Check the pricing page for spacing and contrast','Audit the pricing page for spacing and contrast issues and list fixes.'],['edit','var(--pl)','var(--pl-bg)','Rewrite copy','Make the onboarding intro shorter','Rewrite the onboarding intro so it is shorter and clearer.'],['code','var(--pm)','var(--pm-bg)','Export tokens','Turn colour and spacing into CSS variables','Export the colour and spacing tokens as CSS variables.'],['layers','var(--pp)','var(--pp-bg)','Compare frames','Diff the mobile and desktop frames','Compare the mobile and desktop frames and list the differences.']],
    [['chart','var(--pt)','var(--pt-bg)','Explain a metric','Why did activation drop last week','Explain why activation dropped last week, with sources.'],['mail','var(--pk)','var(--pk-bg)','Draft an email','Announce the new pricing to customers','Draft an email announcing the new pricing to existing customers.'],['bug','var(--pr)','var(--pr-bg)','Find a bug','Trace why checkout logs people out','Find out why checkout logs people out and suggest a fix.'],['figma','var(--pl)','var(--pl-bg)','Build from Figma','Turn the hero frame into code','Build the hero frame from Figma as a React component.']]
  ];
