    go.innerHTML = '<span class="spin"></span>'; await c.wait(800);
    box.classList.add('shut'); await c.wait(300);
    const n = chips.filter(x => x.classList.contains('on')).length;
    const thx = html(`<div class="fbx-thx">${I('ok')}<span>Thanks. The agent will ${n ? 'avoid this' : 'use this'} next time in this project.</span></div>`);
    r.firstElementChild.appendChild(thx); enter(thx); swap(st, 'Feedback sent');
  });
  /* once it has entered, it rates the answer down and fills in the sheet by itself. Anything you do inside it takes over */
  let auto = true; const mine = e => { if (e.isTrusted){ auto = false; ta.classList.remove('typing'); } };
  c.on(r, 'pointerdown', mine, true); c.on(r, 'keydown', mine, true);
  const beat = async ms => { await c.wait(ms); if (!auto) throw 'stop'; };
  c.run(async () => {
    await beat(1500); down(false);
    await beat(1000); chips[1].click();
    await beat(700); ta.classList.add('typing');
    for (const ch of 'Keep our 8px spacing scale'){ ta.value += ch; ready(); await beat(34 + Math.random() * 40); }
    await beat(650); ta.classList.remove('typing'); go.click();
  });
});

