DM.def('permission-gate', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{figma}', I('figma')).replace(/\{chk\}/g, I('check','xs'));
  const root = $('.pgx', r), ok = $('.pgx-ok', r), boxes = $$('.pgx-o input', r);
  let dur = 'This task';
  const count = () => { const n = boxes.filter(b => b.checked).length; ok.disabled = !n; swap(ok, n ? 'Allow ' + n + (n > 1 ? ' scopes' : ' scope') : 'Pick a scope'); };
  boxes.forEach(b => b.onchange = count);
  seg($('.seg2', r), v => dur = v);
  $$('.seg2 button', r).forEach(b => b.dataset.v = b.textContent);
  const body = [...root.children].slice(1);
  function granted(n){
    body.forEach(e => e.hidden = true);
    const d = html(`<div class="pgx-done">${I('ok')}<span class="t">Allowed ${n} ${n > 1 ? 'scopes' : 'scope'} for ${dur.toLowerCase()}<span>Applying the pricing fixes now</span></span><button class="pill ghost sm">Revoke</button></div>`);
    root.appendChild(d); enter(d);
    c.later(1400, () => { const s = $('.t span', d); if (s) swap(s, 'Done. 6 frames edited on a new page'); });
    $('button', d).onclick = () => { d.classList.add('leave'); c.later(300, () => { d.remove(); body.forEach(e => e.hidden = false); stagger(body, 50); }); };
  }
  ok.onclick = () => c.run(async () => { const n = boxes.filter(b => b.checked).length; ok.innerHTML = '<span class="spin"></span>'; await c.wait(600); granted(n); count(); });
  $('.pgx-no', r).onclick = () => { body.forEach(e => e.hidden = true); const d = html(`<div class="pgx-done" style="background:var(--chip)">${I('info')}<span class="t">The agent will skip the Figma edits<span>It will list the fixes in chat instead</span></span><button class="pill ghost sm">Undo</button></div>`); root.appendChild(d); enter(d); $('button', d).onclick = () => { d.remove(); body.forEach(e => e.hidden = false); stagger(body, 50); }; };
});

