/* ---------- page shell ---------- */
:where([data-c]) *{box-sizing:border-box}
:where([data-c]) button,:where([data-c]) input,:where([data-c]) textarea,:where([data-c]) select{font:inherit;color:inherit}
:where([data-c]) button{background:none;border:0;padding:0;cursor:pointer}
:where([data-c]) :focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:6px}
.stage-in{width:100%;max-width:440px;min-width:0;position:relative;container-type:inline-size}
.card.wide .stage-in{max-width:720px}

/* ---------- icons ---------- */
.i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.i.s{width:14px;height:14px}.i.xs{width:12px;height:12px}.i.l{width:18px;height:18px}
.brand{width:16px;height:16px;display:block;flex:none}
.flag{width:20px;height:15px;border-radius:3px;object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

