.mono{font-family:var(--mono)}
.sp{flex:1}
.num{font-variant-numeric:tabular-nums}
.muted{color:var(--muted)}.fg2{color:var(--fg2)}
.panel{background:var(--surface);border-radius:var(--r-card);box-shadow:var(--shadow);position:relative}
.ib{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;color:var(--fg2);transition:background var(--t-fast),color var(--t-fast),transform .15s}
.ib:hover{background:var(--chip);color:var(--fg)}
.ib:active{transform:scale(.94)}
.ib.fill{background:var(--soft);box-shadow:var(--soft-ring)}
.ib.fill:hover{background:var(--soft-h)}
.ib.on{background:var(--accent-bg);color:var(--accent)}
.chip{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border-radius:var(--r-pill);font-size:13px;color:var(--fg2);background:var(--chip);white-space:nowrap;transition:background var(--t-fast),color var(--t-fast),box-shadow var(--t-fast)}
.chip:hover{background:var(--hover);color:var(--fg)}
.chip.on{background:var(--surface);color:var(--fg);box-shadow:inset 0 0 0 1px var(--line)}
.chip.sm{height:24px;padding:0 9px;font-size:12px}
.pill{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:32px;padding:0 14px;border-radius:var(--r-pill);font-size:13px;font-weight:500;white-space:nowrap;transition:background var(--t-fast),color var(--t-fast),opacity var(--t-fast),transform .15s}
.pill:active{transform:scale(.97)}
.pill.ink{background:var(--ink);color:var(--on-ink)}
.pill.ink:hover{opacity:.88}
.pill.accent{background:var(--accent);color:var(--on-accent)}
.pill.accent:hover,.pill.accent.hl{background:var(--accent-2)}
.pill.soft{background:var(--soft);color:var(--fg);box-shadow:var(--soft-ring)}
.pill.soft:hover{background:var(--soft-h)}
.pill.line{background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);color:var(--fg)}
.pill.ghost{color:var(--fg2)}.pill.ghost:hover{background:var(--chip);color:var(--fg)}
.pill[disabled]{opacity:.4;cursor:not-allowed;transform:none}
:where([data-c]) button:disabled{cursor:not-allowed}
.pill:is(.accent,.ink,.soft,.line)[disabled]{opacity:1;background:var(--soft);color:var(--dis);box-shadow:var(--soft-ring)}
.pill.sm{height:28px;padding:0 11px;font-size:12.5px}
.tag{display:inline-flex;align-items:center;gap:5px;height:20px;padding:0 7px;border-radius:6px;font-size:11.5px;font-weight:500;white-space:nowrap;background:var(--chip);color:var(--fg2)}
.tag.b{background:var(--pb-bg);color:var(--pb)}.tag.l{background:var(--pl-bg);color:var(--pl)}.tag.m{background:var(--pm-bg);color:var(--pm)}.tag.p{background:var(--pp-bg);color:var(--pp)}
.tag.r{background:var(--pr-bg);color:var(--pr)}.tag.y{background:var(--py-bg);color:var(--py)}.tag.k{background:var(--pk-bg);color:var(--pk)}.tag.t{background:var(--pt-bg);color:var(--pt)}
.tag.ok{background:var(--ok-bg);color:var(--ok)}.tag.warn{background:var(--warn-bg);color:var(--warn)}.tag.bad{background:var(--bad-bg);color:var(--bad)}
.dot{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none;display:inline-block}
.fchip{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 8px;border-radius:var(--r-pill);background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);font-size:12.5px;color:var(--fg);white-space:nowrap}
.fchip.lnk{cursor:pointer;transition:background var(--t-fast),box-shadow var(--t-fast)}
.fchip.lnk:hover{background:var(--chip);box-shadow:inset 0 0 0 1px var(--rail)}
.ft{font-family:var(--mono);font-size:9.5px;font-weight:600;color:var(--ts);letter-spacing:.02em}
.ft.re{color:var(--react)}.ft.fg{color:var(--pl)}.ft.pdf{color:var(--pr)}.ft.csv{color:var(--pm)}
.kbd{font-family:var(--mono);font-size:10.5px;padding:1px 5px;border-radius:5px;background:var(--chip);color:var(--fg2)}
.pill .kbd{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 4px;margin-right:-6px}
.pill.ink .kbd,.pill.accent .kbd{background:color-mix(in srgb,currentColor 18%,transparent);color:inherit}
code.c{font-family:var(--mono);font-size:12.5px;background:var(--chip);padding:1px 5px;border-radius:5px}
.av{width:22px;height:22px;border-radius:50%;display:inline-grid;place-items:center;font-size:10px;font-weight:600;color:#fff;flex:none}
.hr{height:1px;background:var(--line);border:0;margin:0}
.toggle{width:30px;height:18px;border-radius:9px;background:var(--faint);position:relative;flex:none;transition:background var(--t-fast)}
.toggle::after{content:"";position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.2);transition:transform var(--t) var(--ease)}
.toggle[aria-checked="true"]{background:var(--accent)}
.toggle[aria-checked="true"]::after{transform:translateX(12px)}
.seg2{display:inline-flex;padding:2px;background:var(--chip);border-radius:var(--r-pill);position:relative}
.seg2 button{position:relative;z-index:1;height:26px;padding:0 11px;border-radius:var(--r-pill);font-size:12.5px;color:var(--fg2);transition:color var(--t-fast)}
.seg2 button[aria-pressed="true"]{color:var(--fg)}
.seg2 .knob{position:absolute;top:2px;bottom:2px;border-radius:var(--r-pill);background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left var(--t) var(--ease),width var(--t) var(--ease)}
.seg2 button:focus-visible{outline-offset:-2px;border-radius:var(--r-pill)}
/* demo stages: the component sits centred, the variant switcher sits at the foot of the stage under it */
.stage-in:has(>.dm){align-self:stretch;display:flex}
.dm{width:100%;min-height:328px;display:flex;flex-direction:column;align-items:center;gap:32px}
.dm>.dm-main{margin-block:auto;width:100%;display:flex;flex-direction:column;align-items:center}
.dm>.demo{flex:none;display:flex;justify-content:center}

.bub{align-self:flex-end;max-width:85%;background:var(--hover);border-radius:16px;padding:9px 13px;font-size:14px;line-height:1.45}
.msg{margin:0;font-size:14.5px;line-height:1.65}

/* ---------- status glyphs ---------- */
.spin{width:12px;height:12px;border-radius:50%;border:1.5px solid currentColor;border-right-color:transparent;animation:rot .8s linear infinite;flex:none;display:inline-block}
@keyframes rot{to{transform:rotate(360deg)}}
.radar{position:relative;width:13px;height:13px;flex:none;display:inline-block}
.radar::before{content:"";position:absolute;inset:3.5px;border-radius:50%;background:currentColor}
.radar::after{content:"";position:absolute;inset:0;border-radius:50%;border:1.3px solid currentColor;border-right-color:transparent;animation:rot .9s linear infinite}
/* the rotating thinking mark from Soft 1, four dots turning */
.think{width:14px;height:14px;position:relative;flex:none;display:inline-block}
.think i{position:absolute;width:3.4px;height:3.4px;border-radius:50%;background:currentColor;left:50%;top:50%;margin:-1.7px}
.think i:nth-child(1){transform:translate(-3.6px,-3.6px)}.think i:nth-child(2){transform:translate(3.6px,-3.6px)}.think i:nth-child(3){transform:translate(3.6px,3.6px)}.think i:nth-child(4){transform:translate(-3.6px,3.6px)}
.think.on{animation:thinkrot 1.6s var(--ease-io) infinite}
.think.on i{animation:thinkpulse 1.6s var(--ease-io) infinite}
.think.on i:nth-child(2){animation-delay:.2s}.think.on i:nth-child(3){animation-delay:.4s}.think.on i:nth-child(4){animation-delay:.6s}
@keyframes thinkrot{0%{transform:rotate(0)}50%{transform:rotate(90deg)}100%{transform:rotate(180deg)}}
@keyframes thinkpulse{0%,100%{opacity:1}50%{opacity:.35}}
/* the step that is happening now in a trace: a quiet grey dot with a soft ping */
.pulse{position:relative;width:6px;height:6px;border-radius:50%;background:var(--muted);flex:none;display:inline-block}
.pulse::after{content:"";position:absolute;inset:0;border-radius:50%;background:inherit;animation:ping 1.8s var(--ease) infinite}
@keyframes ping{0%{transform:scale(1);opacity:.45}80%,100%{transform:scale(2.8);opacity:0}}

/* ---------- motion ---------- */
.shim{background:linear-gradient(90deg,var(--fg) 0%,var(--fg) 38%,var(--faint) 50%,var(--fg) 62%,var(--fg) 100%);background-size:260% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:shim 2.2s linear infinite}
@keyframes shim{from{background-position:100% 0}to{background-position:-160% 0}}
.enter{animation:enter var(--t-slow) var(--ease) backwards}
@keyframes enter{from{opacity:0;transform:translateY(6px);filter:blur(4px)}to{opacity:1;transform:none;filter:blur(0)}}
.pop-in{animation:popin .5s var(--ease) backwards}
@keyframes popin{from{opacity:0;transform:scale(.96);filter:blur(3px)}to{opacity:1;transform:none;filter:blur(0)}}
.leave{animation:leave .35s var(--ease) both}
@keyframes leave{to{opacity:0;transform:translateY(-6px);filter:blur(4px)}}
.sw{display:inline-block;transition:opacity .2s var(--ease),filter .2s var(--ease),transform .25s var(--ease)}
.sw.out{opacity:0;filter:blur(3px);transform:translateY(3px)}
.fold{display:grid;grid-template-rows:1fr;transition:grid-template-rows var(--t) var(--ease),opacity var(--t) var(--ease)}
.fold>*{overflow:hidden;min-height:0}
.fold.shut{grid-template-rows:0fr;opacity:0}

/* ---------- tooltip and popover ---------- */
.tip{position:fixed;z-index:1000;pointer-events:none;background:var(--ink);color:var(--on-ink);font-size:12px;line-height:1.35;padding:6px 9px;border-radius:8px;max-width:240px;opacity:0;transform:translateY(4px);filter:blur(2px);transition:opacity .18s var(--ease),transform .25s var(--ease),filter .18s}
.tip.show{opacity:1;transform:none;filter:none}
.copied,.copied:hover{color:var(--ok)!important}
.tip .kbd{background:rgba(255,255,255,.14);color:inherit;margin-left:6px}
:root[data-theme="dark"] .tip .kbd{background:rgba(0,0,0,.1)}
:root[data-theme="dark"] .av{color:#151518!important}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .av{color:#151518!important}}
.pop{position:absolute;z-index:50;min-width:200px;background:var(--raised);border-radius:14px;box-shadow:var(--shadow-pop);padding:6px;opacity:0;pointer-events:none;transform:translateY(6px) scale(.98);transform-origin:var(--origin,top left);filter:blur(3px);transition:opacity .2s var(--ease),transform .35s var(--ease),filter .2s var(--ease)}
.pop.open{opacity:1;pointer-events:auto;transform:none;filter:none}
.pop .ph{padding:6px 8px 4px;font-size:11.5px;color:var(--muted)}
.mi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;border-radius:9px;font-size:13px;text-align:left;color:var(--fg);transition:background var(--t-fast)}
.mi:hover,.mi.hl{background:var(--row)}
.mi .i{color:var(--fg2)}
.mi .d{display:block;font-size:12px;color:var(--muted)}
.mi .r{margin-left:auto;color:var(--muted);font-size:12px}
.mi .ck{margin-left:auto;color:var(--accent);opacity:0;transition:opacity var(--t-fast)}
.mi[aria-checked="true"] .ck{opacity:1}
.mi[aria-checked="true"]{background:var(--row);font-weight:500}
.pop .sep{height:1px;background:var(--line);margin:4px 2px}
/* every list row hovers with --row; an icon chip or track inside a hovered row lifts above it (white in light mode, one step lighter in dark) */
:root[data-theme="dark"] :is(.alg-it:hover .alg-ic,.plx-s:hover .n,.tpx-r:hover .tr){background:var(--hover)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) :is(.alg-it:hover .alg-ic,.plx-s:hover .n,.tpx-r:hover .tr){background:var(--hover)}}

@media (prefers-reduced-motion:reduce){:where([data-c]) *,:where([data-c]) *::before,:where([data-c]) *::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.shim{color:var(--fg);background:none}}

/* bare: components that live in the chat stream sit on the chat surface, no card */
.card.bare .stage-in .panel:not(.keep){background:none;box-shadow:none;padding-left:0;padding-right:0;border-radius:0}
/* chart palette, saturated */
:root{--c1:#116ff8;--c2:#7c4dff;--c3:#00b37e;--c4:#ff8a00;--c5:#ff4d6d;--c6:#00b8d9}
:root[data-theme="dark"]{--c1:#3d8bff;--c2:#9b7bff;--c3:#22c993;--c4:#ffa033;--c5:#ff6b85;--c6:#22cce8}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--c1:#3d8bff;--c2:#9b7bff;--c3:#22c993;--c4:#ffa033;--c5:#ff6b85;--c6:#22cce8}}

/* ---------- Blueprint 2 ---------- */
/* Blueprint 2: the same components drawn as a technical sheet. Square corners, hairline edges instead of shadows,
   an orange accent, and motion that wipes and ticks into place in short, hard beats instead of blurring in */
:root:not([data-style="soft"]){
  --motion:bp;
  --page:#f3f3f0; --stage:#fafaf8; --surface:#ffffff; --raised:#ffffff;
  --fg:#121212; --fg2:#4a4a46; --muted:#72726c; --faint:#bdbdb6; --rail:#d2d2cb; --line:#e3e3dd;
  --chip:#f1f1ed; --hover:#e8e8e3; --press:#dededa; --wash:#f6f6f3; --row:color-mix(in srgb,var(--fg) 4%,transparent);
  --soft:#ebebe6; --soft-h:#e1e1db; --soft-ring:inset 0 0 0 1px rgba(20,20,12,.09); --dis:#a3a39c;
  --accent:#f76b00; --accent-2:#d65c00; --accent-bg:#fff2e8; --on-accent:#ffffff; --sel:color-mix(in srgb,var(--accent) 7%,transparent);
  --ink:#121212; --on-ink:#ffffff;
  --shadow:0 0 0 1px var(--line);
  --shadow-pop:0 0 0 1px var(--rail),0 12px 28px -14px rgba(20,20,12,.22);
  --shadow-toast:0 0 0 1px var(--rail),0 10px 24px -14px rgba(20,20,12,.24);
  --shadow-lift:0 0 0 1px var(--fg);
  --grid:rgba(20,20,12,.09); --tick:#b5b5ad;
  --ease:cubic-bezier(.65,0,.25,1); --ease-io:cubic-bezier(.65,0,.25,1);
  --t-fast:.14s; --t:.3s; --t-slow:.44s;
}
@media (prefers-color-scheme:dark){:root:not([data-style="soft"]):not([data-theme="light"]){
  --page:#111111; --stage:#1c1c1c; --surface:#262626; --raised:#2c2c2c;
  --fg:#f2f2f2; --fg2:#ababab; --muted:#8c8c8c; --faint:#555555; --rail:#414141; --line:#333333;
  --chip:#303030; --hover:#373737; --press:#3f3f3f; --wash:#2c2c2c; --row:color-mix(in srgb,var(--fg) 5.5%,transparent);
  --soft:#323232; --soft-h:#3a3a3a; --soft-ring:inset 0 0 0 1px rgba(255,255,255,.08); --dis:#5f5f5f;
  --accent:#ff850d; --accent-2:#ff9b3d; --accent-bg:rgba(255,133,13,.12); --on-accent:#ffffff; --sel:color-mix(in srgb,var(--accent) 10%,transparent);
  --ink:#f2f2f2; --on-ink:#161616;
  --shadow:0 0 0 1px var(--line);
  --shadow-pop:0 0 0 1px var(--rail),0 16px 32px -14px rgba(0,0,0,.7);
  --shadow-toast:0 0 0 1px var(--rail),0 12px 28px -14px rgba(0,0,0,.7);
  --shadow-lift:0 0 0 1px var(--fg2);
  --grid:rgba(255,255,255,.07); --tick:#55554f;
  --ease:cubic-bezier(.65,0,.25,1); --ease-io:cubic-bezier(.65,0,.25,1);
  --t-fast:.14s; --t:.3s; --t-slow:.44s}}
:root:not([data-style="soft"])[data-theme="dark"]{
  --page:#111111; --stage:#1c1c1c; --surface:#262626; --raised:#2c2c2c;
  --fg:#f2f2f2; --fg2:#ababab; --muted:#8c8c8c; --faint:#555555; --rail:#414141; --line:#333333;
  --chip:#303030; --hover:#373737; --press:#3f3f3f; --wash:#2c2c2c; --row:color-mix(in srgb,var(--fg) 5.5%,transparent);
  --soft:#323232; --soft-h:#3a3a3a; --soft-ring:inset 0 0 0 1px rgba(255,255,255,.08); --dis:#5f5f5f;
  --accent:#ff850d; --accent-2:#ff9b3d; --accent-bg:rgba(255,133,13,.12); --on-accent:#ffffff; --sel:color-mix(in srgb,var(--accent) 10%,transparent);
  --ink:#f2f2f2; --on-ink:#161616;
  --shadow:0 0 0 1px var(--line);
  --shadow-pop:0 0 0 1px var(--rail),0 16px 32px -14px rgba(0,0,0,.7);
  --shadow-toast:0 0 0 1px var(--rail),0 12px 28px -14px rgba(0,0,0,.7);
  --shadow-lift:0 0 0 1px var(--fg2);
  --grid:rgba(255,255,255,.07); --tick:#55554f;
  --ease:cubic-bezier(.65,0,.25,1); --ease-io:cubic-bezier(.65,0,.25,1);
  --t-fast:.14s; --t:.3s; --t-slow:.44s}

/* every corner is square, only the turning loaders stay round */
:root:not([data-style="soft"]) *,:root:not([data-style="soft"]) *::before,:root:not([data-style="soft"]) *::after{border-radius:0!important}
:root:not([data-style="soft"]) .spin,:root:not([data-style="soft"]) .radar::before,:root:not([data-style="soft"]) .radar::after{border-radius:50%!important}
:root:not([data-style="soft"]) svg:not(.i):not(.brand) rect{rx:0;ry:0}
:root:not([data-style="soft"]) svg:not(.i):not(.brand) :is(path,line,polyline,circle){stroke-linecap:butt}
/* no blur anywhere: things wipe in or cut, they never soften */
:root:not([data-style="soft"]) *,:root:not([data-style="soft"]) *::before,:root:not([data-style="soft"]) *::after{filter:none!important}

/* the sheet: cards share their hairlines, every stage is drafting paper with crop marks in the corners */
:root:not([data-style="soft"]) .seg2 .knob{box-shadow:0 0 0 1px var(--rail)}

/* parts: mono labels, hairline controls, hatched when disabled */
:root:not([data-style="soft"]) .tag{font-family:var(--mono);font-size:10.5px;font-weight:500;letter-spacing:.03em;text-transform:uppercase;height:19px;padding:0 6px}
:root:not([data-style="soft"]) .kbd{box-shadow:inset 0 0 0 1px var(--line)}
:root:not([data-style="soft"]) .pill.line{box-shadow:inset 0 0 0 1px var(--rail)}
:root:not([data-style="soft"]) .pill.line:hover{background:var(--wash);box-shadow:inset 0 0 0 1px var(--faint)}
:root:not([data-style="soft"]) .pill:active,:root:not([data-style="soft"]) .ib:active{transform:translateY(1px)}
:root:not([data-style="soft"]) .pill:is(.accent,.ink,.soft,.line)[disabled]{background-image:repeating-linear-gradient(135deg,transparent 0 4px,var(--grid) 4px 5px)}
:root:not([data-style="soft"]) .chip.on{box-shadow:inset 0 0 0 1px var(--rail)}
:root:not([data-style="soft"]) .mcx-add{box-shadow:none;outline:1px dashed var(--rail);outline-offset:-1px}
:root:not([data-style="soft"]) .bub{background:var(--chip);box-shadow:inset 0 0 0 1px var(--line)}
:root:not([data-style="soft"]) .tip{box-shadow:none}

/* motion: a top-down wipe that settles on a hard ease, stepped loaders, a blinking cursor instead of a soft ping */
@keyframes bpin{0%{opacity:0;clip-path:inset(0 0 100% 0);transform:translateY(4px)}30%{opacity:1}100%{opacity:1;clip-path:inset(0 0 0 0);transform:none}}
@keyframes bpout{to{opacity:0;clip-path:inset(0 0 100% 0)}}
@keyframes bpblink{0%,55%{opacity:1}56%,100%{opacity:.2}}
:root:not([data-style="soft"]) .enter,:root:not([data-style="soft"]) .pop-in{animation-name:bpin;animation-duration:var(--t-slow);animation-timing-function:var(--ease);animation-fill-mode:backwards}
:root:not([data-style="soft"]) .leave{animation:bpout .26s var(--ease) both}
:root:not([data-style="soft"]) .chx-card.show{animation:bpin .34s var(--ease) backwards}
:root:not([data-style="soft"]) .sw.out{transform:translateY(-3px)}
:root:not([data-style="soft"]) .pop{transform:translateY(4px);transition-duration:.16s}
:root:not([data-style="soft"]) .pop.open{transform:none}
:root:not([data-style="soft"]) .spin{animation:rot .9s steps(8) infinite}
:root:not([data-style="soft"]) .radar::after{animation:rot 1s steps(8) infinite}
:root:not([data-style="soft"]) .pulse{animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .pulse::after{display:none}
:root:not([data-style="soft"]) .btx-ask::after{background:linear-gradient(90deg,transparent 0 40%,rgba(255,255,255,.38) 40% 46%,transparent 46%)}
:root:not([data-style="soft"]) .btx-ask:hover::after{transition:transform .5s steps(10)}
:root:not([data-style="soft"]) .btx-live::after{display:none}
:root:not([data-style="soft"]) .btx-live{animation:bpblink 1.1s steps(1,end) infinite}

/* a component card: the template renders into .stage-in */
[data-c]{width:440px;max-width:100%;font-family:var(--sans);font-size:14px;line-height:1.5;color:var(--fg);-webkit-font-smoothing:antialiased}
[data-c].wide{width:720px}

