.btx-hold{position:relative;overflow:hidden;background:var(--bad-bg);color:var(--bad);user-select:none;-webkit-user-select:none;touch-action:none}
.btx-hold .fill{position:absolute;inset:0;background:var(--bad);transform-origin:left;transform:scaleX(0);transition:transform .25s var(--ease)}
