DM.def('tooltip', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{undo}', I('undo')).replace('{chat}', I('edit')).replace('{spark}', I('spark')).replace('{users}', I('users')).replace('{a1}', AV('MK','var(--pl)')).replace('{a2}', AV('DA','var(--pb)'));
  const P = [['MK','var(--pl)','Maya Kim','Design lead','Editing Pricing, frame 2'],['DA','var(--pb)','Design agent','Working for Maya','Auditing contrast, 2 of 6 checks']];
  const card = $('.ttp-card', r), ci = $('.ttp-ci', r), root = $('.ttp', r); let t;
  $$('.ttp-av', r).forEach(b => { b.onmouseenter = () => { clearTimeout(t); t = setTimeout(() => { const p = P[+b.dataset.card];
      ci.innerHTML = `<div class="ttp-ch">${AV(p[0], p[1])}<div><b>${p[2]}</b><span>${p[3]}</span></div></div><div class="ttp-cs">${p[0] === 'DA' ? '<span class="think on" style="color:var(--accent)"><i></i><i></i><i></i><i></i></span>' : '<span class="dot"></span>'}${p[4]}</div>`;
      const rr = root.getBoundingClientRect(), br = b.getBoundingClientRect(); let x = br.left - rr.left + br.width / 2 - 115; x = Math.max(0, Math.min(x, rr.width - 230));
      card.style.left = x + 'px'; card.style.top = (br.bottom - rr.top + 10) + 'px'; card.classList.add('show'); }, 300); };
    b.onmouseleave = () => { clearTimeout(t); card.classList.remove('show'); }; });
  c.offs.push(() => clearTimeout(t));
  // once it has entered, it shows what it does: a shortcut tip, then the agent's card. Pointing at it takes over
  let touched = false; c.on(root, 'pointerenter', () => { touched = true; });
  c.run(async () => {
    await c.wait(1300); if (touched || tipFor) return;
    const ask = $('[data-tip-k="⌘J"]', r); showTip(ask); await c.wait(1700); if (touched) return; if (tipFor === ask) hideTip();
    await c.wait(500); if (touched) return;
    const av = $('.ttp-av[data-card="1"]', r); av.onmouseenter(); await c.wait(2600); if (!touched) av.onmouseleave();
  });
});

