DM.def('thinking', (r, c) => {
  const tk = $('.tk', r), list = $('.tk-list', r), title = $('.tk-title', r), time = $('.tk-time', r), head = $('.tk-h', r), fold = $('.tk-fold', r), mark = $('.think', r);
  const chips = `<div class="tk-chips"><button class="fchip lnk" data-tip="Figma, 6 frames read">${I('figma','xs')}Pricing.fig</button><button class="fchip lnk" data-tip="src/styles/tokens.ts, 212 lines"><span class="ft">TS</span>tokens.ts</button><button class="fchip lnk" data-tip="src/components/PricingCard.tsx"><span class="ft re">TSX</span>PricingCard.tsx</button><button class="fchip lnk" data-tip="w3.org, WCAG 2.2 contrast">${I('globe','xs')}Contrast guide</button><button class="tk-more" data-tip="Button.tsx, globals.css">+2 more</button></div>`;
  const steps = [
    { mk:'search', run:'Searching the design system', done:'Searched the design system', chips:true, ms:1600 },
    { run:'Reading 1 of 6 frames', done:'Read 6 frames from Pricing.fig', count:6, ms:1500 },
    { run:'Checking if the old grid is in the tokens', done:"Dead end: the old grid isn't in tokens.ts", dead:true, ms:1400 },
    { run:'Mapping every spacing value', done:'Mapped 9 spacing values', ms:1300 },
    { run:'Comparing desktop and mobile', done:'Compared desktop and mobile', sub:true, ms:1100 },
    { run:'Finding values off the 8px grid', done:'3 values break the 8px grid', sub:true, ms:1000 },
    { run:'Merging both breakpoints', done:'Merged both breakpoints', hollow:true, ms:1000 },
    { run:'Spotting cards that need a fix', done:'Found 3 cards to fix', ms:1200 },
    { run:'Drafting the fix', done:'Drafted a 2-step fix', ms:1300 }
  ];
  const setOpen = o => { tk.dataset.open = o ? '1' : '0'; fold.classList.toggle('shut', !o); head.setAttribute('aria-expanded', o); };
  head.onclick = () => setOpen(tk.dataset.open !== '1');
  // a finished line settles where it is: the shimmer stops and the new words sharpen out of a soft blur, never fading to nothing and back
  const settle = (el, text) => {
    el.style.transition = 'none'; el.classList.remove('shim'); el.textContent = text; void el.offsetWidth; el.style.transition = '';
    if (REDUCE) return;
    const bp = getComputedStyle(el).getPropertyValue('--motion').trim() === 'bp';
    el.animate(bp ? [{ opacity:.6 }, { opacity:1 }] : [{ opacity:.6, filter:'blur(1.5px)' }, { opacity:1, filter:'blur(0)' }], { duration:bp ? 220 : 460, easing:bp ? 'steps(3, end)' : 'cubic-bezier(.22,1,.36,1)' });
  };
  let secs = 0, live = true; c.every(1000, () => { if (live){ secs++; time.textContent = secs + 's'; } });
  c.run(async () => {
    await c.wait(800);
    let prev = null;
    for (const s of steps){
      if (prev) $('.rl', prev).classList.add('on');
      const li = html(`<li class="tk-st run${s.sub ? ' sub' : ''}${s.dead ? ' dead' : ''}">${s.sub ? '<span class="curve"></span>' : ''}<span class="mk"><span class="pulse"></span></span><span class="rl"></span><div class="tx"><span class="lab shim">${s.run}</span></div></li>`);
      list.appendChild(li); enter(li);
      const lab = $('.lab', li), tx = $('.tx', li);
      if (s.chips){ await c.wait(550); tx.insertAdjacentHTML('beforeend', chips); stagger($$('.fchip,.tk-more', tx), 80);
        const more = $('.tk-more', tx); more.onclick = () => { hideTip(); const add = html(`<span style="display:contents"><button class="fchip lnk" data-tip="src/components/Button.tsx"><span class="ft re">TSX</span>Button.tsx</button><button class="fchip lnk" data-tip="src/styles/globals.css"><span class="ft">CSS</span>globals.css</button></span>`); more.replaceWith(add); stagger($$('.fchip', add), 70); }; }
      // the count changes in place under the shimmer, so the line never blinks
      if (s.count){ for (let n = 2; n <= s.count; n++){ await c.wait(s.ms / s.count); lab.textContent = 'Reading ' + n + ' of ' + s.count + ' frames'; } }
      else await c.wait(s.ms);
      settle(lab, s.done); li.classList.remove('run');
      const mk = $('.mk', li);
      mk.innerHTML = s.mk === 'search' ? I('search','xs') : s.dead ? I('x','xs') : s.hollow ? '<span class="ring"></span>' : '<span class="dot"></span>';
      enter(mk.firstElementChild);
      prev = li;
    }
    await c.wait(500); live = false; $('.rl', prev).classList.add('on');
    const fin = html(`<li class="tk-st tk-fin"><span class="mk">${I('ok','s')}</span><div class="tx"><span><span class="lab">Finished thinking</span><span class="sum">3 cards to fix · 2 steps</span></span></div></li>`);
    list.appendChild(fin); enter(fin);
    mark.classList.remove('on'); settle(title, 'Thought for ' + Math.max(secs, 1) + 's'); time.textContent = '';
    await c.wait(2200); setOpen(false);
  });
});

