.ecx-day{border-left:1px solid var(--line)}
.ecx-dh{height:32px;display:flex;align-items:center;justify-content:center;gap:5px;font-size:12px;color:var(--fg2);border-bottom:1px solid var(--line)}
.ecx-dh b{font-weight:500;color:var(--fg)}
.ecx-dh.t b{width:22px;height:22px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center;font-size:11.5px}
.ecx-col{position:relative;height:352px;background-image:linear-gradient(var(--line) 1px,transparent 1px);background-size:100% 44px}
.ecx-e{position:absolute;left:3px;right:3px;border-radius:8px;padding:4px 7px;font-size:11.5px;line-height:1.3;text-align:left;overflow:hidden;transition:transform .25s var(--ease),box-shadow .25s}
.ecx-e:hover{transform:translateY(-1px);box-shadow:var(--shadow)}
