DM.def('agent-run-timeline', (r, c) => {
  const T = 12;
  const S = [
    { l:'Plan the change', ic:'brain', s:0, d:1.6, c:'var(--c2)', cost:.03 },
    { l:'Read 6 files', ic:'file-text', s:1.6, d:2.2, c:'var(--c1)', cost:.02 },
    { l:'Search Figma', ic:'figma', s:1.9, d:1.4, c:'var(--c6)', cost:.01 },
    { l:'Edit PricingCard', ic:'edit', s:4, d:2.4, c:'var(--c2)', cost:.06 },
    { l:'Run tests', ic:'term', s:6.5, d:1.5, c:'var(--c3)', cost:.01, fail:true },
    { l:'Run tests, retry', ic:'refresh', s:8.1, d:1.9, c:'var(--c3)', cost:.01 },
    { l:'Open PR', ic:'pr', s:10.1, d:1.3, c:'var(--c4)', cost:.02 }
  ];
  $('.art-ticks', r).innerHTML = [0,3,6,9,12].map(t => `<span style="left:${t / T * 100}%">${t}s</span>`).join('');
  const rows = $('.art-rows', r), head = $('.art-head', r);
  S.forEach(s => { s.el = html(`<div class="art-row"><span class="art-lab">${I(s.ic,'xs')}<span class="t">${s.l}</span></span><span class="art-lane"><span class="art-bar${s.fail ? ' fail' : ''}" style="--c:${s.c};left:${s.s / T * 100}%" data-tip="${s.l}: ${s.d.toFixed(1)}s, $${s.cost.toFixed(2)}${s.fail ? ', 2 tests failed' : ''}"></span></span></div>`); rows.appendChild(s.el); });
  stagger($$('.art-row', r), 50);
  $('.art-f', r).innerHTML = '<span><b>0.0s</b> total</span><span><b>$0.00</b> cost</span><span><b>0</b> steps</span><span><b>0</b> retries</span>';
  const lanes = () => $('.art-lane', r).getBoundingClientRect();
  c.run(async () => {
    await c.wait(500);
    const t0 = performance.now();
    const f = $('.art-f', r);
    const foot = (secs, cost, n, re) => { f.innerHTML = `<span><b>${secs.toFixed(1)}s</b> total</span><span><b>$${cost.toFixed(2)}</b> cost</span><span><b>${n}</b> step${n === 1 ? '' : 's'}</span><span><b>${re}</b> retr${re === 1 ? 'y' : 'ies'}</span>`; };
    await new Promise(res => c.loop(() => {
      const t = Math.min(T, (performance.now() - t0) / 1000 * 1.6);
      const L = lanes(), gx = $('.art-grid', r).getBoundingClientRect();
      const on = S.filter(s => t >= s.s); foot(Math.min(t, 11.4), on.reduce((a, s) => a + s.cost * Math.min(1, (t - s.s) / s.d), 0), on.length, on.filter(s => s.ic === 'refresh').length);
      head.style.left = (L.left - gx.left + t / T * L.width) + 'px';
      S.forEach(s => { const w = Math.max(0, Math.min(s.d, t - s.s)); $('.art-bar', s.el).style.width = (w / T * 100) + '%'; });
      const now = S.filter(s => t >= s.s && t < s.s + s.d).map(s => s.l);
      $('.art-s', r).textContent = now.length ? now.join(', ') : 'Wrapping up';
      if (t >= T){ res(); return false; }
    }));
    head.style.opacity = 0;
    const tag = $('.art-tag', r); tag.className = 'art-tag tag ok'; tag.innerHTML = I('check','xs') + 'Done'; enter(tag);
    swap($('.art-s', r), 'Finished in 11.4s');
    foot(11.4, .16, 7, 1);
  });
});

