DM.def('onboarding-checklist', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs')).replace('{check}', I('check','xs'));
  const S = [['Create your workspace','Done when you signed up',1,0],['Connect Figma','So the agent can read your frames',0,1],['Import your tokens','Colours, type and spacing',0,1],['Invite a teammate','Design is better together',0,0],['Run your first audit','Takes about a minute',0,1]];
  const list = $('.obx-list', r), st = $('.obx-st', r), ring = $('.obx-ring', r), rw = $('.obx-rw', r), fl = $('.obx-ring .fl', r);
  list.innerHTML = S.map((s, i) => `<div class="obx-s${s[2] ? ' done' : ''}" data-i="${i}"><button class="obx-ck" role="checkbox" aria-checked="${!!s[2]}" aria-label="${s[0]}">${I('check','xs')}</button><span class="t"><b>${s[0]}</b><span>${s[1]}</span></span>${s[3] ? `<button class="pill soft sm">${I('spark','xs')}Do it for me</button>` : ''}</div>`).join('');
  const rows = $$('.obx-s', list);
  function tally(){ const n = S.filter(s => s[2]).length; fl.style.strokeDashoffset = 100.5 * (1 - n / S.length); ring.classList.toggle('full', n === S.length); rw.classList.toggle('full', n === S.length); swap(st, n === S.length ? 'All done. Nice work' : n + ' of ' + S.length + ' done');
    if (n === S.length && !$('.obx-dn', list)){ const d = html(`<div class="obx-dn">${I('ok','xs')}You are all set. The agent will suggest what to try next.</div>`); list.appendChild(d); enter(d); } else if (n < S.length) $('.obx-dn', list)?.remove(); }
  const set = (i, v) => { S[i][2] = v; rows[i].classList.toggle('done', v); $('.obx-ck', rows[i]).setAttribute('aria-checked', v); tally(); };
  rows.forEach((row, i) => {
    $('.obx-ck', row).onclick = () => set(i, !S[i][2]);
    // the whole row ticks the step, not only its checkbox (its button does its own thing, and a running step waits)
    row.onclick = e => { if (e.target.closest('.obx-ck, .pill') || row.classList.contains('run')) return; set(i, !S[i][2]); };
    const p = $('.pill', row); if (p) p.onclick = () => c.run(async () => { row.classList.add('run'); const ck = $('.obx-ck', row); ck.innerHTML = '<span class="spin" style="width:14px;height:14px"></span>'; const sp = $('.t span', row), was = sp.textContent; swap(sp, 'The agent is on it'); sp.classList.add('shim');
      await c.wait(1400); ck.innerHTML = I('check','xs'); row.classList.remove('run'); sp.classList.remove('shim'); swap(sp, was); set(i, 1); });
  });
  const mn = $('.obx-min', r); mn.onclick = () => { const s = $('.obx-fold', r).classList.toggle('shut'); mn.classList.toggle('shut', s); mn.dataset.tip = s ? 'Expand' : 'Collapse'; };
  stagger(rows, 50); c.later(200, tally);
  c.later(1300, () => $('.pill', rows[1]).click());
});

c73.css:
/* ---------- Stepper ---------- */
/* the agent walks you through setup in the chat: no container; with .panel it becomes a card */
.stx{padding:16px 0;display:flex;flex-direction:column;gap:16px}
.stx.panel{padding:16px}
.stx-track{display:flex;align-items:center;gap:0}
.stx-st{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--muted);white-space:nowrap;transition:color .3s}
.stx-st .n{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:11.5px;font-weight:500;box-shadow:inset 0 0 0 1.5px var(--line);color:var(--muted);transition:background .35s var(--ease),box-shadow .35s,color .35s;flex:none}
.stx-st.on{color:var(--fg)}
.stx-st.on .n{box-shadow:inset 0 0 0 1.5px var(--accent),0 0 0 4px var(--accent-bg);color:var(--accent)}
.stx-st.done{color:var(--fg2);cursor:pointer}
.stx-st.done .n{background:var(--accent);box-shadow:none;color:#fff}
.stx-ln{flex:1;height:2px;margin:0 10px;border-radius:1px;background:var(--line);position:relative;overflow:hidden;min-width:16px}
.stx-ln i{position:absolute;inset:0;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.stx-ln.full i{transform:none}
@media (max-width:520px){.stx-st .lb{display:none}.stx-st.on .lb{display:inline}}
/* each step sits in the middle, the same distance from the track above and the buttons below */
.stx-vp{overflow-x:clip;overflow-y:visible;min-height:150px;display:flex;flex-direction:column;justify-content:center}
.stx-body{display:flex;flex-direction:column;gap:10px}
.stx-body.inr{animation:stxr .45s var(--ease) both}.stx-body.inl{animation:stxl .45s var(--ease) both}
@keyframes stxr{from{opacity:0;transform:translateX(24px);filter:blur(4px)}}
@keyframes stxl{from{opacity:0;transform:translateX(-24px);filter:blur(4px)}}
.stx-body h4{margin:0;font-size:14.5px;font-weight:500}
.stx-body p{margin:0;font-size:12.5px;color:var(--muted)}
.stx-opts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
@media (max-width:520px){.stx-opts{grid-template-columns:1fr}}
.stx-o{padding:12px;border-radius:12px;background:var(--chip);text-align:left;font-size:13px;display:flex;flex-direction:column;gap:4px;transition:background .2s,box-shadow .25s}
.stx-o span{font-size:11.5px;color:var(--muted)}
.stx-o:hover{background:var(--hover)}
/* the picked option: a white tile with a quiet hairline */
.stx-o.on{background:var(--surface);box-shadow:inset 0 0 0 1px var(--rail),0 1px 2px rgba(0,0,0,.04)}
.stx-f{display:flex;justify-content:space-between}
.stx-bk[disabled]{visibility:hidden}
.stx-dn{display:flex;flex-direction:column;align-items:center;gap:6px;padding:18px 0;text-align:center;font-size:13px}
.stx-dn>b{font-size:14.5px;font-weight:500}
/* finished: the check pops and draws itself, a soft ring spreads from it, and a little confetti bursts out once */
.stx-ok{position:relative;width:44px;height:44px;margin-bottom:6px}
.stx-ok svg{display:block;width:44px;height:44px;overflow:visible}
.stx-ok .c{fill:var(--ok);transform-origin:center;transform-box:fill-box}
.stx-ok .k{fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:24}
.stx-ok::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none}
.stx-dn.go .stx-ok .c{animation:stxpop .6s var(--ease) both}
.stx-dn.go .stx-ok .k{animation:stxdraw .42s var(--ease) .26s both}
.stx-dn.go .stx-ok::after{animation:stxring 1.2s var(--ease) .18s}
@keyframes stxpop{from{transform:scale(.3);opacity:0}60%{transform:scale(1.08);opacity:1}to{transform:none;opacity:1}}
@keyframes stxdraw{from{stroke-dashoffset:24}to{stroke-dashoffset:0}}
@keyframes stxring{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--ok) 32%,transparent)}to{box-shadow:0 0 0 20px color-mix(in srgb,var(--ok) 0%,transparent)}}
.stx-conf{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.stx-conf i{position:absolute;left:0;top:0;border-radius:2px;opacity:0}
.stx-conf i.d{border-radius:50%}

