DM.def('plan-review', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{plus}', I('plus','xs'));
  const S = ['Read the pricing frames and the brand tokens', 'Compare against the three competitor pages', 'Simplify the plan cards to one CTA each', 'Move the FAQ below the comparison table', 'Write a summary of every change'];
  const list = $('.plx-list', r), st = $('.plx-st', r), go = $('.plx-go', r), f = $('.plx-f', r);
  const row = (t, i) => `<li class="plx-s"><span class="n">${i + 1}</span><span class="t" contenteditable="true" spellcheck="false">${t}</span><button class="ib plx-x" aria-label="Skip step" data-tip="Skip step">${I('x','xs')}</button></li>`;
  list.innerHTML = S.map(row).join(''); stagger($$('.plx-s', list), 60, 100);
  const count = () => { const on = $$('.plx-s:not(.off)', list); on.forEach((s, i) => $('.n', s).textContent = i + 1); $$('.plx-s.off .n', list).forEach(n => n.textContent = '–'); swap(st, on.length + ' steps, about ' + Math.max(1, Math.round(on.length * .8)) + ' min'); };
  function bind(s){
    const t = $('.t', s), orig = t.textContent;
    t.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } };
    t.onblur = () => s.classList.toggle('edited', t.textContent.trim() !== orig);
    $('.plx-x', s).onclick = () => { const off = s.classList.toggle('off'); $('.plx-x', s).dataset.tip = off ? 'Include step' : 'Skip step'; $('.plx-x', s).innerHTML = I(off ? 'undo' : 'x', 'xs'); count(); };
  }
  $$('.plx-s', list).forEach(bind);
  $('.plx-add', r).onclick = () => { const s = html(row('New step', 0)); list.appendChild(s); enter(s); bind(s); count(); const t = $('.t', s); t.focus(); document.getSelection().selectAllChildren(t); };
  $('.plx-chg', r).onclick = () => { swap($('.plx-n', r), 'Tell the agent what to change in chat'); };
  go.onclick = () => c.run(async () => {
    $$('.t', list).forEach(t => t.contentEditable = 'false'); $('.plx-add', r).hidden = true;
    // the approved plan is fixed: the skip buttons keep their space but can't be used
    $$('.plx-x', list).forEach(b => { b.disabled = true; b.style.visibility = 'hidden'; });
    f.innerHTML = `<span class="muted plx-n">Running the approved plan</span><button class="pill ghost sm plx-stop">${I('stop','xs')}Stop</button>`; stagger([...f.children], 50);
    let stop = false; $('.plx-stop', f).onclick = () => stop = true;
    $('.plx-mk', r).classList.add('on');
    const on = $$('.plx-s:not(.off)', list);
    for (let i = 0; i < on.length && !stop; i++){
      const s = on[i]; s.classList.add('run'); swap(st, 'Step ' + (i + 1) + ' of ' + on.length); await c.wait(900);
      s.classList.remove('run'); s.classList.add('done'); $('.n', s).innerHTML = I('check','xs');
    }
    $('.plx-mk', r).classList.remove('on');
    swap(st, stop ? 'Stopped, progress kept' : 'Done. 4 frames updated'); f.innerHTML = `<span class="muted plx-n"></span><button class="pill soft sm">${I('eye','xs')}See changes</button>`; enter(f.lastElementChild);
  });
});

