/* ---------- Error and recovery ---------- */
.erx{padding:8px}
.erx-h{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px 6px}
.erx-t{font-weight:500}
.erx-s{font-size:12.5px;white-space:nowrap}
.erx-list{padding:2px 10px 6px}
.erx-row{position:relative;display:flex;gap:10px;padding:6px 0 6px 24px;font-size:13.5px;color:var(--fg)}
.erx-row .g{position:absolute;left:0;top:7px;width:16px;height:16px;display:grid;place-items:center}
.erx-row:not(:last-child)::before{content:"";position:absolute;left:7.5px;top:25px;bottom:-6px;width:1px;background:var(--rail)}
.erx-row .d{display:block;font-size:12.5px;color:var(--muted);transition:color .3s}
.erx-row.wait{color:var(--muted)}
.erx-row.fail .d{color:var(--bad)}
.erx-row.skip .tx{text-decoration:line-through;color:var(--muted)}
.erx-in{margin:4px 0 0;padding:8px 10px 2px}
.erx-q{font-size:13px;font-weight:500;margin-bottom:8px}
