.erx-o{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:10px;font-size:13px;text-align:left;color:var(--fg2);transition:background .25s,color .25s}
.erx-o:hover{background:var(--row);color:var(--fg)}
.erx-o.on{background:var(--sel);color:var(--fg)}
.erx-o i{width:15px;height:15px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--faint);flex:none;transition:box-shadow .35s var(--ease)}
.erx-o.on i{box-shadow:inset 0 0 0 4.5px var(--accent)}

