DM.def('error-recovery', (r, c) => {
  const list = $('.erx-list', r), box = $('.erx-box', r), go = $('.erx-go', r), sum = $('.erx-s', r), opts = $$('.erx-o', r);
  const steps = [['Pull 1,240 deals from the CRM'],['Write to the Pipeline 2026 sheet'],['Post the summary in #sales']];
  list.innerHTML = steps.map(s => `<div class="erx-row"><span class="g"></span><span class="tx">${s[0]}<span class="d"></span></span></div>`).join('');
  const rows = $$('.erx-row', r);
  const G = { done:`<span style="color:var(--ok)">${I('check','xs')}</span>`, fail:`<span style="color:var(--bad)">${I('alert','xs')}</span>`, run:'<span class="spin"></span>', wait:'<span class="dot" style="color:var(--faint)"></span>', skip:`<span class="muted">${I('chev-r','xs')}</span>`, hand:`<span style="color:var(--pl)">${I('user','xs')}</span>` };
  const set = (i, st, note) => { const rw = rows[i]; rw.className = 'erx-row ' + st; const g = $('.g', rw); g.innerHTML = G[st]; enter(g); swap($('.d', rw), note || ''); };
  set(0, 'done', 'Done in 8s'); set(1, 'fail', 'Error 403: the agent lost edit access to this sheet'); set(2, 'wait');
  let pick = 'retry';
  opts.forEach(o => o.onclick = () => { pick = o.dataset.o; opts.forEach(x => { x.classList.toggle('on', x === o); x.setAttribute('aria-checked', x === o); }); });
  go.onclick = () => c.run(async () => {
    box.classList.add('shut');
    if (pick === 'retry'){
      set(1, 'run', 'Asking for edit access'); swap(sum, 'Recovering'); await c.wait(1200);
      set(1, 'run', 'Access granted, retrying'); await c.wait(1000);
      set(1, 'done', 'Wrote 1,240 rows'); set(2, 'run'); await c.wait(1000);
      set(2, 'done', 'Posted to 14 people'); swap(sum, 'Recovered');
    } else if (pick === 'skip'){
      set(1, 'skip', 'Skipped, nothing was written'); set(2, 'run'); await c.wait(1000);
      set(2, 'done', 'Posted, with a note about the sheet'); swap(sum, '2 of 3 done');
    } else {
      set(1, 'hand', 'Maya has the error, the logs and the last good state'); swap(sum, 'Waiting on Maya');
    }
  });
});

c110.css:
/* ---------- Tools and connections ---------- */
.hnx{padding:12px;display:flex;flex-direction:column;gap:6px}
.hnx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:2px 10px 8px}
.hnx-h>div{display:flex;flex-direction:column}
.hnx-h b{font-weight:500;font-size:13.5px}
.hnx-st{font-size:12px}
.hnx-list{display:flex;flex-direction:column}
.hnx-t{display:flex;align-items:center;gap:12px;padding:8px 10px;border-radius:12px;font-size:13px;transition:background .2s}
.hnx-t:hover{background:var(--row)}
.hnx-t .ic{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;flex:none;position:relative}
.hnx-t .ic::after{content:"";position:absolute;right:-2px;bottom:-2px;width:8px;height:8px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 2px var(--surface);transition:background .3s}
.hnx-t.off .ic::after{background:var(--faint)}
.hnx-t .ic.brandic{background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);color:var(--fg)}
.hnx-t .ic .brand{width:15px;height:15px}
.hnx-t.err .ic::after{background:var(--bad)}
.hnx-t.chk .ic::after{background:var(--accent);animation:hnp 1s ease-in-out infinite}
@keyframes hnp{50%{transform:scale(1.4);opacity:.5}}
.hnx-t .t{flex:1;min-width:0;display:flex;flex-direction:column}
.hnx-t .t span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hnx-t.err .t span{color:var(--bad)}
/* the same pill switch as every other segmented switch; its track darkens with a hovered row so it never melts into it */
.hnx-pm{display:grid;grid-template-columns:repeat(3,auto);padding:2px;border-radius:var(--r-pill);background:var(--chip);position:relative;transition:background-color .2s}
.hnx-t:hover .hnx-pm{background:color-mix(in srgb,var(--fg) 8%,transparent)}
.hnx-pm button{position:relative;z-index:1;height:24px;padding:0 9px;border-radius:var(--r-pill);font-size:11.5px;color:var(--muted);transition:color .2s}
.hnx-pm button:hover{color:var(--fg2)}
.hnx-pm button[aria-pressed="true"]{color:var(--fg)}
.hnx-pm button:focus-visible{outline-offset:-2px}
.hnx-pm .kn{position:absolute;top:2px;bottom:2px;border-radius:var(--r-pill);background:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left .4s var(--ease),width .4s var(--ease)}
.hnx-add{display:flex;align-items:center;gap:8px;height:30px;padding:0 12px 0 10px;font-size:12.5px;color:var(--fg2);border-radius:var(--r-pill);align-self:flex-start;transition:background-color .2s,color .2s}
.hnx-add:hover{color:var(--fg);background:var(--chip)}
.hnx-pop{min-width:220px}

